function validate([board]) {
  if (!Array.isArray(board) || board.length < 3 || board.length > 500) return 'board needs 3 to 500 rows.';
  const n = board[0].length;
  if (n < 3 || n > 500) return 'board needs 3 to 500 columns.';
  if (board.some(row => row.length !== n)) return 'Every row of board must have the same length.';
  if (board.some(row => row.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9))) return 'Each cell is an integer from -10^9 to 10^9.';
  return null;
}

