function maximumValueSum(board) {
  const m = board.length;
  const n = board[0].length;
  const bestThree = (colBest) => {
    const top = [];
    for (let col = 0; col < n; col++) {
      top.push([colBest[col], col]);
      top.sort((a, b) => b[0] - a[0]);
      if (top.length > 3) top.pop();
    }
    return top;
  };
  const below = new Array(m);
  const colBelow = new Array(n).fill(-Infinity);
  for (let row = m - 1; row >= 2; row--) {
    for (let col = 0; col < n; col++) {
      colBelow[col] = Math.max(colBelow[col], board[row][col]);
    }
    below[row] = bestThree(colBelow);
  }
  const colAbove = new Array(n).fill(-Infinity);
  let best = -Infinity;
  for (let mid = 1; mid < m - 1; mid++) {
    for (let col = 0; col < n; col++) {
      colAbove[col] = Math.max(colAbove[col], board[mid - 1][col]);
    }
    const above = bestThree(colAbove);
    for (let col = 0; col < n; col++) {
      for (const [upValue, upCol] of above) {
        for (const [downValue, downCol] of below[mid + 1]) {
          if (col !== upCol && col !== downCol && upCol !== downCol) {
            best = Math.max(best, upValue + board[mid][col] + downValue);
          }
        }
      }
    }
  }
  return best;
}

