function maximumValueSum(board) {
  const m = board.length, n = board[0].length;
  let best = -Infinity;
  // Every set of three rows, and every way to give them three different columns.
  for (let r1 = 0; r1 < m; r1++)
    for (let r2 = r1 + 1; r2 < m; r2++)
      for (let r3 = r2 + 1; r3 < m; r3++)
        for (let c1 = 0; c1 < n; c1++)
          for (let c2 = 0; c2 < n; c2++)
            for (let c3 = 0; c3 < n; c3++)
              if (c1 !== c2 && c1 !== c3 && c2 !== c3)
                best = Math.max(best, board[r1][c1] + board[r2][c2] + board[r3][c3]);
  return best;
}

