function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const m = size === 'small' ? int(3, 6) : int(80, 100);
  const n = size === 'small' ? int(3, 6) : int(80, 100);
  const style = rand();
  const span = size === 'large' || style < 0.3 ? 1e9 : style < 0.6 ? 20 : 3;
  // Sometimes one or two "hot" columns hold most of the large values, so rows compete for them.
  const hot = style > 0.5 ? [int(0, n - 1), int(0, n - 1)] : [];
  const negative = rand() < 0.15;
  const cell = (col) => {
    if (negative) return int(-span, -1);
    if (!hot.length) return int(-span, span);
    if (hot.includes(col) && rand() < 0.7) return int(Math.floor(span / 2), span);
    return int(-span, Math.floor(span / 2));
  };
  return [Array.from({ length: m }, () => Array.from({ length: n }, (_, col) => cell(col)))];
}
